<?php require __DIR__.'/../includes/bootstrap.php'; admin_required();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if($id&&is_valid_status($status)){db()->prepare('UPDATE appointments SET status=?, confirmed_at=IF(?="confirmado",COALESCE(confirmed_at,NOW()),confirmed_at) WHERE id=?')->execute([$status,$status,$id]);}header('Location: appointments.php?date='.urlencode($_GET['date']??date('Y-m-d')));exit;}
$date=$_GET['date']??date('Y-m-d');$st=db()->prepare('SELECT a.*,c.name client_name,c.phone,c.email,s.name service_name,s.duration_minutes FROM appointments a JOIN clients c ON c.id=a.client_id JOIN services s ON s.id=a.service_id WHERE a.appointment_date=? ORDER BY a.appointment_time');$st->execute([$date]);$items=$st->fetchAll();
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agenda | PG Estética</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-shell"><?php include '_nav.php'; ?><section><div class="container"><div class="admin-heading"><div><span class="eyebrow">agenda clínica</span><h1>Agendamentos</h1></div><form method="get" class="inline-form"><input type="date" name="date" value="<?= e($date) ?>"><button class="btn btn-outline">Abrir data</button></form></div><div class="day-nav"><a href="?date=<?= date('Y-m-d',strtotime($date.' -1 day')) ?>">← dia anterior</a><strong><?= date('d/m/Y',strtotime($date)) ?></strong><a href="?date=<?= date('Y-m-d',strtotime($date.' +1 day')) ?>">próximo dia →</a></div><div class="table-wrap"><table><thead><tr><th>Horário</th><th>Cliente</th><th>Serviço</th><th>Contato</th><th>Status</th><th>WhatsApp</th></tr></thead><tbody><?php foreach($items as $a): ?><tr><td><strong><?= substr($a['appointment_time'],0,5) ?></strong><br><span class="small muted"><?= (int)$a['duration_minutes'] ?> min</span></td><td><a href="client.php?id=<?= (int)$a['client_id'] ?>"><strong><?= e($a['client_name']) ?></strong></a><?php if($a['notes']): ?><br><span class="small muted"><?= e($a['notes']) ?></span><?php endif; ?></td><td><?= e($a['service_name']) ?></td><td><?= e($a['phone']) ?><br><span class="small"><?= e($a['email']) ?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><select name="status" onchange="this.form.submit()"><?php foreach(['pendente','confirmado','concluido','cancelado','nao_compareceu'] as $stt): ?><option value="<?= $stt ?>" <?= $a['status']===$stt?'selected':'' ?>><?= str_replace('_',' ',$stt) ?></option><?php endforeach; ?></select></form></td><td><a class="btn btn-outline btn-small" target="_blank" href="https://wa.me/<?= e($a['phone']) ?>?text=<?= urlencode('Olá '.$a['client_name'].', falando da PG Estética sobre seu horário de '.date('d/m/Y',strtotime($a['appointment_date'])).' às '.substr($a['appointment_time'],0,5).'.') ?>">Mensagem</a></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="6" class="center muted">Nenhum agendamento nesta data.</td></tr><?php endif; ?></tbody></table></div></div></section></body></html>
